/**
 * N1: GL/JE numbers used to be generated by reading the highest existing
 * number sorted as TEXT, then +1, with no lock — two posts at once could be
 * handed the same number, and a period past 9999 sorted "10000" behind
 * "9999" so every entry after that collided. This proves the fix:
 * DocumentNumberService.getNextDocumentNumber allocates via a row-locked
 * counter inside the caller's own transaction, so concurrent allocations can
 * never collide and a heavy month keeps counting past 9999 with no
 * collision or truncation.
 *
 * Runs against tenant_test, never a real tenant — see
 * billCreationAtomicity.test.js's own header comment for why this uses
 * getTenantConnection rather than tests/setup/testDb.js's getSequelize()
 * (the dual sequelize-package hazard).
 */
const tenantContext = require('../../src/server/tenantContext');
const { getTenantConnection } = require('../../src/server/tenantDb');

const TEST_CLINIC_ID = 1;
const TEST_SCHEMA = process.env.DB_SCHEMA || 'tenant_test';
const TEST_PERIOD_DATE = '2099-11-15'; // far-future period so this test never collides with real data

let sequelize;
let testConn;
let AccountingService;
let getNextDocumentNumber;
let cashAccountId;
let receivableAccountId;

function withTenant(fn) {
  return tenantContext.run(testConn, fn);
}

beforeAll(async () => {
  testConn = await getTenantConnection(TEST_SCHEMA);
  sequelize = testConn.sequelize;
  sequelize.options.logging = false;
  AccountingService = require('../../src/server/services/AccountingService');
  ({ getNextDocumentNumber } = require('../../src/server/services/DocumentNumberService'));

  const [[cash]] = await sequelize.query(`SELECT id FROM chart_of_accounts WHERE clinic_id = :c AND account_code = '1100'`, { replacements: { c: TEST_CLINIC_ID } });
  const [[receivable]] = await sequelize.query(`SELECT id FROM chart_of_accounts WHERE clinic_id = :c AND account_code = '1200'`, { replacements: { c: TEST_CLINIC_ID } });
  cashAccountId = cash.id;
  receivableAccountId = receivable.id;
}, 30000);

afterAll(async () => {
  try {
    await sequelize.query(`DELETE FROM gl_line_items WHERE gl_id IN (SELECT id FROM general_ledger WHERE description LIKE 'GLNUM-TEST-%')`);
    await sequelize.query(`DELETE FROM account_ledger WHERE transaction_id IN (SELECT id FROM general_ledger WHERE description LIKE 'GLNUM-TEST-%')`);
    await sequelize.query(`DELETE FROM general_ledger WHERE description LIKE 'GLNUM-TEST-%'`);
    await sequelize.query(`DELETE FROM document_number_counters WHERE period = '209911'`);
  } catch (e) { console.warn('glNumbering cleanup failed (non-fatal):', e.message); }
});

describe('N1: DocumentNumberService.getNextDocumentNumber', () => {
  test('concurrent allocations for the same clinic/type/period never collide', async () => {
    const numbers = await Promise.all(
      Array.from({ length: 8 }, () => withTenant(async () => {
        const t = await sequelize.transaction();
        const num = await getNextDocumentNumber('GL', TEST_CLINIC_ID, t, { date: TEST_PERIOD_DATE });
        await t.commit();
        return num;
      }))
    );
    expect(new Set(numbers).size).toBe(numbers.length);
    for (const n of numbers) expect(n).toMatch(/^GL-209911-\d{4,}$/);
  });

  test('widens past 9999 instead of wrapping or truncating', async () => {
    await withTenant(async () => {
      await sequelize.query(
        `INSERT INTO document_number_counters (clinic_id, doc_type, period, last_number)
         VALUES (:c, 'JE', '209912', 9999)
         ON CONFLICT (clinic_id, doc_type, period) DO UPDATE SET last_number = 9999`,
        { replacements: { c: TEST_CLINIC_ID } }
      );
      const t = await sequelize.transaction();
      const num = await getNextDocumentNumber('JE', TEST_CLINIC_ID, t, { date: '2099-12-01' });
      await t.commit();
      expect(num).toBe('JE-209912-10000');
    });
    await sequelize.query(`DELETE FROM document_number_counters WHERE period = '209912'`);
  });

  test('a transaction is required — this is meaningless without one', async () => {
    await expect(getNextDocumentNumber('GL', TEST_CLINIC_ID, null)).rejects.toThrow(/requires an open transaction/);
  });
});

describe('N1: AccountingService.createGLEntry allocates through the same mechanism', () => {
  test('two entries created concurrently (via the same real posting path) get distinct, balanced numbers', async () => {
    const post = () => withTenant(() => AccountingService.createGLEntry(
      {
        clinic_id: TEST_CLINIC_ID,
        transaction_date: new Date().toISOString().split('T')[0],
        transaction_type: 'test',
        description: `GLNUM-TEST-${Date.now()}-${Math.random()}`,
      },
      [
        { account_id: cashAccountId, debit_amount: 100, credit_amount: 0, description: 'GLNUM-TEST debit' },
        { account_id: receivableAccountId, debit_amount: 0, credit_amount: 100, description: 'GLNUM-TEST credit' },
      ],
      'test-system'
    ));

    const [a, b] = await Promise.all([post(), post()]);
    expect(a.gl_number).not.toBe(b.gl_number);
    expect(a.is_balanced).toBe(true);
    expect(b.is_balanced).toBe(true);
  });
});
